inline std::string windowsFont(const std::string&content){auto required=codepoints(content);HDC dc=CreateCompatibleDC(nullptr);if(!dc)throw std::runtime_error("Could not create PDF font context.");std::string result;for(auto face:{L"Microsoft YaHei",L"Microsoft JhengHei",L"Segoe UI",L"Arial"}){HFONT font=CreateFontW(-16,0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_TT_PRECIS,CLIP_DEFAULT_PRECIS,DEFAULT_QUALITY,DEFAULT_PITCH,face);if(!font)continue;auto old=SelectObject(dc,font);DWORD size=GetFontData(dc,0,0,nullptr,0);try{if(size==GDI_ERROR||size<12||size>32*1024*1024)throw std::runtime_error("Font data unavailable.");std::string raw(size,'\0');if(GetFontData(dc,0,0,raw.data(),size)!=size)throw std::runtime_error("Font data read failed.");auto count=be16(raw,4);if(count>128||(size_t)(12+count*16)>raw.size())throw std::runtime_error("Invalid font directory.");std::map<std::string,std::string>tables;for(unsigned i=0;i<count;i++){auto tag=raw.substr(12+i*16,4);DWORD id=(unsigned char)tag[0]|((DWORD)(unsigned char)tag[1]<<8)|((DWORD)(unsigned char)tag[2]<<16)|((DWORD)(unsigned char)tag[3]<<24);DWORD n=GetFontData(dc,id,0,nullptr,0);if(n==GDI_ERROR||n>32*1024*1024)throw std::runtime_error("Font table unavailable.");std::string bytes(n,'\0');if(n&&GetFontData(dc,id,0,bytes.data(),n)!=n)throw std::runtime_error("Font table read failed.");tables[tag]=std::move(bytes);}result=sfnt(tables);TrueType check(result);for(auto cp:required)if(cp>=32&&!check.glyph(cp))throw std::runtime_error("Font lacks document characters.");}catch(...){result.clear();}SelectObject(dc,old);DeleteObject(font);if(!result.empty())break;}DeleteDC(dc);if(result.empty())throw std::runtime_error("No embeddable TrueType font covers the PDF text. Try removing unsupported symbols or install fonts for the document language.");return result;}
inline Gdiplus::Color drawingColor(const std::string&value,Gdiplus::Color fallback){if(value.empty())return fallback;if(value=="none"||value=="transparent")return Gdiplus::Color(0,0,0,0);if((value.size()!=7&&value.size()!=9)||value[0]!='#')throw std::runtime_error("Colors must use #RRGGBB or #AARRGGBB.");uint32_t n=0;for(size_t i=1;i<value.size();i++){char c=value[i];unsigned digit=c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:99;if(digit>15)throw std::runtime_error("Invalid drawing color.");n=(n<<4)|digit;}if(value.size()==7)n|=0xff000000;return Gdiplus::Color(n);}
inline std::string encodedBitmap(Gdiplus::Bitmap&bitmap,const std::string&ext){UINT count=0,size=0;Gdiplus::GetImageEncodersSize(&count,&size);if(!size||size>1024*1024)throw std::runtime_error("Image encoders unavailable.");std::vector<unsigned char>bytes(size);auto*codecs=(Gdiplus::ImageCodecInfo*)bytes.data();if(Gdiplus::GetImageEncoders(count,size,codecs)!=Gdiplus::Ok)throw std::runtime_error("Image encoders unavailable.");const wchar_t*mime=ext==".jpg"||ext==".jpeg"?L"image/jpeg":ext==".bmp"?L"image/bmp":ext==".tif"||ext==".tiff"?L"image/tiff":L"image/png";CLSID encoder{};bool found=false;for(UINT i=0;i<count;i++)if(wcscmp(codecs[i].MimeType,mime)==0){encoder=codecs[i].Clsid;found=true;break;}if(!found)throw std::runtime_error("This Windows installation has no encoder for the image format.");IStream*stream=nullptr;if(FAILED(CreateStreamOnHGlobal(nullptr,TRUE,&stream)))throw std::runtime_error("Could not allocate image output.");Gdiplus::EncoderParameters settings{};ULONG quality=92;settings.Count=1;settings.Parameter[0].Guid=Gdiplus::EncoderQuality;settings.Parameter[0].Type=Gdiplus::EncoderParameterValueTypeLong;settings.Parameter[0].NumberOfValues=1;settings.Parameter[0].Value=&quality;auto status=bitmap.Save(stream,&encoder,(ext==".jpg"||ext==".jpeg")?&settings:nullptr);if(status!=Gdiplus::Ok){stream->Release();throw std::runtime_error("Image encoding failed.");}STATSTG stat{};stream->Stat(&stat,STATFLAG_NONAME);if(stat.cbSize.QuadPart>32*1024*1024){stream->Release();throw std::runtime_error("Encoded image exceeds 32 MiB.");}std::string output((size_t)stat.cbSize.QuadPart,'\0');LARGE_INTEGER zero{};stream->Seek(zero,STREAM_SEEK_SET,nullptr);ULONG got=0;auto hr=stream->Read(output.data(),(ULONG)output.size(),&got);stream->Release();if(FAILED(hr)||got!=output.size())throw std::runtime_error("Could not read encoded image.");return output;}
inline std::string image(const std::string&content,const std::string&ext){using namespace Gdiplus;auto spec=canvas(content);Bitmap bitmap(spec.width,spec.height,PixelFormat32bppARGB);if(bitmap.GetLastStatus()!=Ok)throw std::runtime_error("Could not allocate image canvas.");Graphics g(&bitmap);g.SetSmoothingMode(SmoothingModeAntiAlias);g.SetTextRenderingHint(TextRenderingHintAntiAliasGridFit);auto background=drawingColor(spec.root.at("background").str,Color(255,248,250,253));if(ext==".jpg"||ext==".jpeg"||ext==".bmp"){g.Clear(Color(255,255,255));SolidBrush bg(background);g.FillRectangle(&bg,0,0,spec.width,spec.height);}else g.Clear(background);for(auto&e:spec.root.at("elements").arr){auto kind=e.at("type").str;auto x=(float)bounded(e,"x",0,-32768,32768),y=(float)bounded(e,"y",0,-32768,32768),w=(float)bounded(e,"width",std::max(0.f,spec.width-x),0,32768),h=(float)bounded(e,"height",std::max(0.f,spec.height-y),0,32768);auto fill=drawingColor(e.at("fill").str,kind=="text"?Color(255,37,51,73):Color(255,31,156,155)),stroke=drawingColor(e.at("stroke").str,kind=="line"?Color(255,37,51,73):Color(0,0,0,0));SolidBrush brush(fill);float sw=(float)bounded(e,"strokeWidth",1,0,100);Pen pen(stroke,sw);if(kind=="text"){Font font(L"Segoe UI",(float)bounded(e,"fontSize",24,4,300),e.at("bold").number?FontStyleBold:FontStyleRegular,UnitPixel);StringFormat format;auto align=e.at("align").str;format.SetAlignment(align=="center"?StringAlignmentCenter:align=="right"?StringAlignmentFar:StringAlignmentNear);auto text=wide(e.at("text").str);g.DrawString(text.c_str(),(INT)text.size(),&font,RectF(x,y,std::max(1.f,w),std::max(1.f,h)),&format,&brush);}else if(kind=="line"){g.DrawLine(&pen,x,y,(float)bounded(e,"x2",0,-32768,32768),(float)bounded(e,"y2",0,-32768,32768));}else if(kind=="polygon"){std::vector<PointF>points;for(auto&p:e.at("points").arr)points.push_back(PointF((float)p.arr[0].number,(float)p.arr[1].number));if(fill.GetA())g.FillPolygon(&brush,points.data(),(INT)points.size());if(stroke.GetA()&&sw>0)g.DrawPolygon(&pen,points.data(),(INT)points.size());}else if(kind=="ellipse"){if(fill.GetA())g.FillEllipse(&brush,x,y,w,h);if(stroke.GetA()&&sw>0)g.DrawEllipse(&pen,x,y,w,h);}else{float radius=(float)std::min<double>(bounded(e,"radius",0,0,32768),std::min(w,h)/2);GraphicsPath path;if(radius<.1f)path.AddRectangle(RectF(x,y,w,h));else{float d=radius*2;path.AddArc(x,y,d,d,180,90);path.AddArc(x+w-d,y,d,d,270,90);path.AddArc(x+w-d,y+h-d,d,d,0,90);path.AddArc(x,y+h-d,d,d,90,90);path.CloseFigure();}if(fill.GetA())g.FillPath(&brush,&path);if(stroke.GetA()&&sw>0)g.DrawPath(&pen,&path);}}g.Flush(FlushIntentionSync);return encodedBitmap(bitmap,ext);}
inline std::string generate(const std::string&ext,const std::string&content){if(ext==".pdf")return pdf(content,windowsFont(content));if(raster(ext))return image(content,ext);return portable(ext,content);}
